// Memory rom: 638495-words x 32-bit
//------------------------------------------------------------------------------
// Port 0 | Read: Sync  | Write: ---- | 
reg [31:0] rom[0:638494];
initial begin
	$readmemh("xilinx_vc707_rom.init", rom);
end
reg [31:0] rom_dat0;
always @(posedge sys_clk) begin
	rom_dat0 <= rom[main_romlinuxsoc_romlinuxsoc_adr];
end
assign main_romlinuxsoc_romlinuxsoc_dat_r = rom_dat0;


//------------------------------------------------------------------------------
// Memory sram: 2048-words x 32-bit
//------------------------------------------------------------------------------
// Port 0 | Read: Sync  | Write: Sync | Mode: Write-First | Write-Granularity: 8
reg [31:0] sram[0:2047];
initial begin
	$readmemh("xilinx_vc707_sram.init", sram);
end
reg [10:0] sram_adr0;
always @(posedge sys_clk) begin : mem_write_block
	integer we_index;
	for(we_index = 0; we_index < 4; we_index=we_index+1)
		if (main_romlinuxsoc_ram_we[we_index])
			sram[main_romlinuxsoc_ram_adr][we_index*8 +: 8] <= main_romlinuxsoc_ram_dat_w[we_index*8 +: 8];
	sram_adr0 <= main_romlinuxsoc_ram_adr;
end
assign main_romlinuxsoc_ram_dat_r = sram[sram_adr0];


//------------------------------------------------------------------------------
// Memory mem: 70-words x 8-bit
//------------------------------------------------------------------------------
