	$readmemh("xilinx_vc707_mem.init", mem);
end
reg [7:0] mem_dat0;
always @(posedge sys_clk) begin
	mem_dat0 <= mem[romlinuxbuilder_csr_bankarray_adr];
end
assign romlinuxbuilder_csr_bankarray_dat_r = mem_dat0;


