always @(posedge sys_clk) begin
	if (main_romlinuxsoc_uart_core_tx_fifo_wrport_we)
		storage[main_romlinuxsoc_uart_core_tx_fifo_wrport_adr] <= main_romlinuxsoc_uart_core_tx_fifo_wrport_dat_w;
end
always @(posedge sys_clk) begin
	if (main_romlinuxsoc_uart_core_tx_fifo_rdport_re) begin
		storage_dat1 <= storage[main_romlinuxsoc_uart_core_tx_fifo_rdport_adr];
